package com.voicegeely.app.tts

import java.io.File
import java.util.Locale

/**
 * Runtime guard for the training-compatible Vietnamese G2P lexicon generated by vig2p.
 *
 * We never silently send an uncovered Vietnamese word to eSpeak because that would use
 * a different frontend from the one used by Kokoro-Vietnamese training/inference.
 */
class KokoroVietnameseTextFrontend private constructor(
    /** word → phoneme tokens (the rest of the lexicon line), in file order. */
    private val entries: LinkedHashMap<String, String>
) {
    private val lexiconWords: Set<String> get() = entries.keys

    /**
     * How Sherpa (1.12+) really handles a multi-language Kokoro model (metadata version 2):
     * - with `lang` empty it uses the model's metadata `voice` ("vi"), and that value can never be
     *   empty, so every non-Chinese text goes straight to eSpeak — the vig2p lexicon was never used
     *   and Kokoro got eSpeak phonemes it was not trained on (wrong Vietnamese);
     * - only text in U+4E00..U+9FFF goes through the lexicon (PhraseMatcher + word2ids).
     *
     * So every lexicon word gets a one-character alias in that range ([alias]); the model text is
     * the aliases plus plain punctuation, no spaces, and each lexicon entry ends with a private
     * token that [sherpaTokens] maps to Kokoro's space id. Every word then reaches exactly its
     * vig2p phonemes, with the word gaps Kokoro was trained on.
     */
    private val aliases: Map<String, String> = entries.keys.withIndex().associate { (i, w) -> w to alias(i) }

    /** Lexicon for Sherpa: alias, vig2p phonemes, then the word-gap token. */
    fun sherpaLexicon(): String = buildString {
        entries.forEach { (word, phones) ->
            append(aliases.getValue(word)).append(' ').append(phones).append(' ').append(SPACE_TOKEN).append('\n')
        }
    }

    /** Text handed to Kokoro: aliases and single punctuation marks only. */
    fun modelText(prepared: Prepared): String {
        val out = StringBuilder()
        var pendingPunct: Char? = null
        val text = prepared.speakableText
        var i = 0
        while (i < text.length) {
            val m = WORD.find(text, i)
            val end = m?.range?.first ?: text.length
            // Between words: keep one Sherpa punctuation mark (the last one), drop spaces/others.
            for (c in text.substring(i, end)) {
                val mapped = PUNCT_MAP[c]
                if (mapped != null) pendingPunct = mapped
            }
            if (m == null) break
            val alias = aliases[m.value]
            if (alias != null) {
                if (pendingPunct != null && out.isNotEmpty()) out.append(pendingPunct)
                pendingPunct = null
                out.append(alias)
            }
            i = m.range.last + 1
        }
        if (out.isNotEmpty()) out.append(pendingPunct ?: '.')
        return out.toString()
    }

    data class Prepared(
        val text: String,
        val missingWords: Set<String> = emptySet()
    ) {
        val covered: Boolean get() = missingWords.isEmpty()

        /**
         * Text that can still be spoken: words missing from the lexicon (for example an app
         * name or a detail string from a backend) are dropped instead of silencing the whole
         * reply. Empty when nothing speakable remains.
         */
        val speakableText: String
            get() = if (covered) text else WORD.replace(text) { if (it.value in missingWords) "" else it.value }
                .replace(Regex("\\s+([,.!?])"), "$1")
                .replace(Regex("\\s+"), " ")
                .trim()
                .takeIf { WORD.containsMatchIn(it) }
                .orEmpty()
    }

    fun prepare(raw: String): Prepared {
        val normalized = normalize(raw)
        val words = WORD.findAll(normalized).map { it.value }.toSet()
        val missing = words.filterNot { it in lexiconWords }.toSortedSet()
        return Prepared(normalized, missing)
    }

    companion object {
        internal val WORD = Regex("[\\p{L}\\p{M}\\d]+")
        private val VI_LOCALE = Locale("vi", "VN")

        fun fromLexicon(file: File): KokoroVietnameseTextFrontend {
            require(file.isFile && file.length() > 0L) { "Kokoro Vietnamese lexicon is missing: ${file.absolutePath}" }
            val entries = LinkedHashMap<String, String>()
            file.useLines { lines ->
                lines.forEach { line ->
                    val trimmed = line.trim()
                    if (trimmed.isEmpty() || trimmed.startsWith("#")) return@forEach
                    val word = trimmed.substringBefore(' ').trim().lowercase(VI_LOCALE)
                    val phones = trimmed.substringAfter(' ', "").trim()
                    if (word.isNotEmpty() && phones.isNotEmpty() && word !in entries) entries[word] = phones
                }
            }
            require(entries.isNotEmpty()) { "Kokoro Vietnamese lexicon is empty" }
            return KokoroVietnameseTextFrontend(entries)
        }

        /** Private-use character used in lexicon entries for Kokoro's word gap (see [sherpaTokens]). */
        const val SPACE_TOKEN = "\uE000"
        private const val ALIAS_BASE = 0x4E00
        private const val ALIAS_LAST = 0x9FFF

        /** Sherpa punctuation tokens (IsPunctuation); other marks map onto them. */
        private val PUNCT_MAP = mapOf(
            ',' to ',', '.' to '.', '!' to '!', '?' to '?', ';' to ',', ':' to ',', '…' to '.'
        )

        /** One CJK character per lexicon word: the only text Sherpa sends through the lexicon. */
        internal fun alias(index: Int): String {
            require(index in 0..(ALIAS_LAST - ALIAS_BASE)) { "lexicon too large for aliases" }
            return (ALIAS_BASE + index).toChar().toString()
        }

        /**
         * tokens.txt for Sherpa: the original tokens plus [SPACE_TOKEN] mapped to the id of the
         * space token (the line whose symbol is blank, e.g. " 16").
         */
        fun sherpaTokens(original: String): String {
            val lines = original.lines().filter { it.isNotEmpty() }
            val spaceId = lines.firstNotNullOfOrNull { line ->
                val id = line.substringAfterLast(' ', "").trim()
                val sym = line.substringBeforeLast(' ', "")
                if (sym.isBlank() && id.toIntOrNull() != null && line.startsWith(" ")) id else null
            } ?: throw IllegalStateException("Kokoro tokens.txt has no space token")
            require(lines.none { it.startsWith(SPACE_TOKEN) }) { "tokens.txt already uses the word-gap token" }
            return lines.joinToString("\n", postfix = "\n") + "$SPACE_TOKEN $spaceId\n"
        }

        fun normalize(text: String): String {
            var out = com.voicegeely.app.voice.SpokenTerms.forSpeech(text.trim())
                .replace("Wi-Fi", "wifi", ignoreCase = true)
                .replace("Follow-Me-Home", "follow me home", ignoreCase = true)
            out = Regex("\\bIP\\b", RegexOption.IGNORE_CASE).replace(out, "ip")
            return out.lowercase(VI_LOCALE)
        }
    }
}
